BEGIN;

DELETE FROM audit_log_entries;
DELETE FROM stock_reservations;
DELETE FROM purchase_order_lines;
DELETE FROM purchase_orders;
DELETE FROM warehouse_stock;
DELETE FROM inventory_items;
DELETE FROM warehouses;



WITH warehouse_seed ("WarehouseNumber", "WarehouseId") AS (
    VALUES
        (1, '00000000-0000-0000-0000-000000000001'::uuid),
        (2, '00000000-0000-0000-0000-000000000002'::uuid),
        (3, '00000000-0000-0000-0000-000000000003'::uuid),
        (4, '00000000-0000-0000-0000-000000000004'::uuid),
        (5, '00000000-0000-0000-0000-000000000005'::uuid)
),
item_stock_seed ("ItemNumber", "InventoryItemId", "BaseQuantity") AS (
    VALUES
        (1, '10000000-0000-0000-0000-000000000001'::uuid, 75.000),
        (2, '10000000-0000-0000-0000-000000000002'::uuid, 90.000),
        (3, '10000000-0000-0000-0000-000000000003'::uuid, 55.000),
        (4, '10000000-0000-0000-0000-000000000004'::uuid, 65.000),
        (5, '10000000-0000-0000-0000-000000000005'::uuid, 80.000),
        (6, '10000000-0000-0000-0000-000000000006'::uuid, 45.000),
        (7, '10000000-0000-0000-0000-000000000007'::uuid, 120.000),
        (8, '10000000-0000-0000-0000-000000000008'::uuid, 95.000),
        (9, '10000000-0000-0000-0000-000000000009'::uuid, 135.000),
        (10, '10000000-0000-0000-0000-000000000010'::uuid, 150.000),
        (11, '10000000-0000-0000-0000-000000000011'::uuid, 60.000),
        (12, '10000000-0000-0000-0000-000000000012'::uuid, 70.000),
        (13, '10000000-0000-0000-0000-000000000013'::uuid, 50.000),
        (14, '10000000-0000-0000-0000-000000000014'::uuid, 110.000),
        (15, '10000000-0000-0000-0000-000000000015'::uuid, 125.000),
        (16, '10000000-0000-0000-0000-000000000016'::uuid, 85.000),
        (17, '10000000-0000-0000-0000-000000000017'::uuid, 40.000),
        (18, '10000000-0000-0000-0000-000000000018'::uuid, 100.000),
        (19, '10000000-0000-0000-0000-000000000019'::uuid, 115.000),
        (20, '10000000-0000-0000-0000-000000000020'::uuid, 35.000)
)
SELECT
    ('20000000-0000-0000-0000-' || lpad(((warehouse_seed."WarehouseNumber" * 100) + item_stock_seed."ItemNumber")::text, 12, '0'))::uuid,
    warehouse_seed."WarehouseId",
    item_stock_seed."InventoryItemId",
    item_stock_seed."BaseQuantity" + (warehouse_seed."WarehouseNumber" * 11) + ((item_stock_seed."ItemNumber" % 4) * 7),
    '2026-01-01T00:00:00+00:00',
    'System Seeder',
    NULL,
    NULL
FROM warehouse_seed
CROSS JOIN item_stock_seed;





COMMIT;
